João 12 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Na ceia em Betânia, quem ungiu os pés de Jesus com bálsamo de nardo?","o":["Marta","Lázaro","Maria","Judas Iscariotes"],"c":2,"v":3,"e":"O versículo 3 diz que Maria ungiu os pés de Jesus e os enxugou com os seus cabelos."},
 {"t":"multipla","p":"Por que Judas reclamou que o perfume não foi vendido?","o":["Porque era ladrão e roubava da bolsa","Porque se importava com os pobres","Porque achava que Jesus não merecia","Porque o perfume era de Marta"],"c":0,"v":6,"e":"O versículo 6 explica que ele não se importava com os pobres, mas era ladrão e roubava da bolsa."},
 {"t":"multipla","p":"O que a multidão levou ao sair ao encontro de Jesus a caminho de Jerusalém?","o":["Mantos","Ramos de palmeiras","Tochas","Pães"],"c":1,"v":13,"e":"O versículo 13 diz que tomaram ramos de palmeiras e saíram ao seu encontro clamando \"Hosana!\"."},
 {"t":"multipla","p":"A quem os gregos se dirigiram pedindo para ver Jesus?","o":["André","Pedro","João","Filipe"],"c":3,"v":21,"e":"O versículo 21 diz que os gregos se dirigiram a Filipe, que era de Betsaida."},
 {"t":"multipla","p":"Quando veio a voz do céu, o que a multidão que ouviu dizia ter sido?","o":["Um terremoto","Um profeta","Um trovão","O vento"],"c":2,"v":29,"e":"O versículo 29 diz que a multidão dizia que havia sido um trovão, e outros, que um anjo lhe falou."},
 {"t":"cv","p":"Os discípulos compreenderam logo, no momento da entrada em Jerusalém, que aquilo estava escrito a respeito de Jesus.","c":false,"v":16,"e":"O versículo 16 diz que não compreenderam a princípio, e só se lembraram quando Jesus foi glorificado."},
 {"t":"cv","p":"Muitos dentre as autoridades creram em Jesus, mas não o confessavam por medo de serem expulsos da sinagoga.","c":true,"v":42,"e":"O versículo 42 diz que, por causa dos fariseus, não o confessavam, temendo serem expulsos da sinagoga."},
 {"t":"cv","p":"Jesus disse que veio ao mundo para julgar o mundo.","c":false,"v":47,"e":"No versículo 47 Jesus diz que não veio para julgar o mundo, mas para salvá-lo."}
]}

João 14 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No começo do capítulo, o que Jesus diz que vai fazer?","o":["Construir um novo templo","Preparar um lugar para os discípulos","Reunir as tribos de Israel","Voltar para a Galileia"],"c":1,"v":2,"e":"No versículo 2, Jesus diz que na casa do Pai há muitas moradas e que vai preparar um lugar para eles."},
 {"t":"multipla","p":"Tomé diz que não sabem o caminho. O que Jesus responde?","o":["Eu sou o caminho, a verdade e a vida","Eu sou a luz do mundo","Eu sou o bom pastor","Eu sou o pão da vida"],"c":0,"v":6,"e":"No versículo 6, Jesus responde a Tomé: \"Eu sou o caminho, a verdade e a vida\"."},
 {"t":"multipla","p":"O que Filipe pede a Jesus?","o":["Que os ensine a orar","Que diga quando vai voltar","Que mostre o Pai a eles","Que os leve junto com ele"],"c":2,"v":8,"e":"No versículo 8, Filipe diz: \"Senhor, mostra-nos o Pai, e isso nos basta\"."},
 {"t":"multipla","p":"O que Jesus diz que o Pai vai dar aos discípulos, a pedido dele?","o":["Uma nova lei","Outro Consolador, para estar com eles para sempre","Um sinal do céu","Autoridade sobre o templo"],"c":1,"v":16,"e":"No versículo 16, Jesus diz que pedirá ao Pai, e Ele dará outro Consolador para estar com eles para sempre."},
 {"t":"multipla","p":"Quem pergunta por que Jesus se manifestaria aos discípulos e não ao mundo?","o":["Tomé","Filipe","Pedro","Judas, não o Iscariotes"],"c":3,"v":22,"e":"No versículo 22, quem faz essa pergunta é Judas, e o texto diz que não é o Iscariotes."},
 {"t":"cv","p":"Jesus diz que o Espírito Santo ensinaria todas as coisas aos discípulos e os lembraria de tudo o que ele tinha dito.","c":true,"v":26,"e":"No versículo 26, Jesus diz que o Espírito Santo ensinará todas as coisas e lembrará tudo o que ele disse."},
 {"t":"cv","p":"Jesus diz que dá a sua paz do mesmo jeito que o mundo dá.","c":false,"v":27,"e":"No versículo 27, Jesus diz que dá a sua paz, mas não a dá como o mundo dá."},
 {"t":"cv","p":"O capítulo termina com Jesus dizendo: \"Levantem-se, vamos embora daqui\".","c":true,"v":31,"e":"No versículo 31, o último do capítulo, Jesus diz: \"Levantem-se, vamos embora daqui\"."}
]}

João 13 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Jesus fez depois de se levantar da mesa e se cingir com a toalha?","o":["Lavou os pés dos discípulos","Partiu o pão e o distribuiu","Orou ao Pai em voz alta","Lavou as próprias mãos"],"c":0,"v":5,"e":"No versículo 5, Jesus derrama água na bacia e começa a lavar os pés dos discípulos, enxugando-os com a toalha."},
 {"t":"multipla","p":"Quando Pedro disse que Jesus nunca lavaria seus pés, o que Jesus respondeu?","o":["Que Pedro não teria parte com ele","Que Pedro era o maior dos discípulos","Que lavaria primeiro os outros","Que Pedro estava todo limpo"],"c":0,"v":8,"e":"No versículo 8, Jesus responde: \"Se eu não os lavar, você não terá parte comigo.\""},
 {"t":"multipla","p":"Depois de lavar os pés dos discípulos, o que Jesus disse que eles também deviam fazer?","o":["Lavar os pés uns dos outros","Jejuar antes da Páscoa","Lavar os pés dos pobres","Purificar-se no templo"],"c":0,"v":14,"e":"No versículo 14, Jesus diz que, se ele lavou os pés deles, também eles devem lavar os pés uns dos outros."},
 {"t":"multipla","p":"Como Jesus mostrou quem era aquele que o trairia?","o":["Deu a ele um pedaço de pão molhado","Apontou para ele na mesa","Disse o nome dele em voz alta","Entregou a ele a bolsa"],"c":0,"v":26,"e":"No versículo 26, Jesus diz que é aquele a quem der o pedaço de pão molhado, e o dá a Judas Iscariotes."},
 {"t":"multipla","p":"Qual é o novo mandamento que Jesus deu aos discípulos?","o":["Que se amem uns aos outros","Que guardem a Páscoa todo ano","Que vendam tudo e deem aos pobres","Que orem sem cessar"],"c":0,"v":34,"e":"No versículo 34, Jesus diz: \"Um novo mandamento eu vos dou: que vos ameis uns aos outros.\""},
 {"t":"cv","p":"Jesus disse aos discípulos que todos eles estavam limpos.","c":false,"v":10,"e":"No versículo 10, Jesus diz \"vocês estão limpos, mas não todos\", porque sabia quem o trairia."},
 {"t":"cv","p":"Como Judas tinha a bolsa, alguns pensaram que Jesus o mandou comprar o necessário para a festa.","c":true,"v":29,"e":"O versículo 29 diz que alguns supunham que Jesus o mandara comprar o necessário para a festa ou dar algo aos pobres."},
 {"t":"cv","p":"Jesus disse que Pedro o negaria duas vezes antes de o galo cantar.","c":false,"v":38,"e":"No versículo 38, Jesus diz que o galo não cantaria antes que Pedro o negasse três vezes."}
]}

João 17 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"No começo da oração, para onde Jesus levantou os olhos?","o":["Ao céu","Aos discípulos","Ao templo","Ao monte"],"c":0,"v":1,"e":"No versículo 1, Jesus levantou os olhos ao céu e disse: Pai, é chegada a hora."},
 {"t":"multipla","p":"Segundo Jesus, em que consiste a vida eterna?","o":["Guardar todos os mandamentos da Lei","Conhecer o único Deus verdadeiro e Jesus Cristo, que ele enviou","Oferecer sacrifícios no templo","Fazer muitas boas obras"],"c":1,"v":3,"e":"No versículo 3, Jesus diz que a vida eterna é conhecer o único Deus verdadeiro e Jesus Cristo, aquele que o Pai enviou."},
 {"t":"multipla","p":"Dos que o Pai lhe deu, quem Jesus diz que se perdeu?","o":["Nenhum deles","Pedro","O filho da perdição","Os fariseus"],"c":2,"v":12,"e":"No versículo 12, Jesus diz que nenhum se perdeu, exceto o filho da perdição, para que a Escritura se cumprisse."},
 {"t":"multipla","p":"O que Jesus pede ao Pai sobre os discípulos e o mundo?","o":["Que os tire do mundo","Que os guarde do mal","Que o mundo deixe de odiá-los","Que os leve com ele imediatamente"],"c":1,"v":15,"e":"No versículo 15, Jesus diz que não pede que os tire do mundo, mas que os guarde do mal."},
 {"t":"multipla","p":"Além dos discípulos, por quem mais Jesus roga?","o":["Pelo mundo inteiro","Pelos sacerdotes do templo","Pelos anjos","Por aqueles que hão de crer nele por meio da palavra deles"],"c":3,"v":20,"e":"No versículo 20, Jesus diz que roga também por aqueles que hão de crer nele por intermédio da palavra dos discípulos."},
 {"t":"cv","p":"Jesus diz que a palavra do Pai é a verdade.","c":true,"v":17,"e":"No versículo 17, Jesus pede: santifica-os na tua verdade; a tua palavra é a verdade."},
 {"t":"cv","p":"Jesus diz que o Pai o amou somente depois da criação do mundo.","c":false,"v":24,"e":"No versículo 24, Jesus diz que o Pai o amou antes da fundação do mundo."},
 {"t":"cv","p":"Jesus diz que continuará a fazer conhecer o nome do Pai.","c":true,"v":26,"e":"No versículo 26, Jesus diz que fez conhecer o nome do Pai e continuará a fazê-lo."}
]}

João 9 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Segundo Jesus, por que o homem nasceu cego?","o":["Porque os pais dele pecaram","Para que se manifestassem nele as obras de Deus","Porque ele mesmo pecou","Para servir de aviso aos fariseus"],"c":1,"v":3,"e":"No versículo 3, Jesus diz que nem ele nem os pais pecaram, mas que aquilo ocorreu para que se manifestassem nele as obras de Deus."},
 {"t":"multipla","p":"Onde Jesus mandou o cego se lavar?","o":["No rio Jordão","No tanque de Betesda","No tanque de Siloé","Numa fonte perto do templo"],"c":2,"v":7,"e":"No versículo 7, Jesus manda o homem se lavar no tanque de Siloé, e ele volta vendo."},
 {"t":"multipla","p":"Em que dia Jesus fez o lodo e abriu os olhos do cego?","o":["No dia da Páscoa","No primeiro dia da semana","Num dia de festa no templo","No sábado"],"c":3,"v":14,"e":"O versículo 14 diz que era sábado o dia em que Jesus fez o lodo e lhe abriu os olhos."},
 {"t":"multipla","p":"O que o homem disse aos fariseus sobre quem lhe abriu os olhos?","o":["Ele é um profeta","Ele é um pecador","Ele é Moisés","Ele é um mestre da Lei"],"c":0,"v":17,"e":"No versículo 17, perguntado sobre quem o curou, o homem responde: Ele é um profeta."},
 {"t":"multipla","p":"Por que os pais disseram aos judeus que perguntassem ao próprio filho?","o":["Porque não reconheciam o filho","Porque temiam os judeus","Porque não tinham visto o filho cego","Porque Jesus lhes pediu silêncio"],"c":1,"v":22,"e":"O versículo 22 diz que os pais falaram assim porque temiam os judeus, já que quem confessasse Jesus como o Cristo seria expulso da sinagoga."},
 {"t":"cv","p":"Quando os fariseus disseram que Jesus era pecador, o homem respondeu: uma coisa sei, eu era cego e agora vejo.","c":true,"v":25,"e":"No versículo 25, o homem diz que não sabe se Jesus é pecador, mas sabe que era cego e agora vê."},
 {"t":"cv","p":"Os fariseus disseram ao homem que eles eram discípulos de Abraão.","c":false,"v":28,"e":"No versículo 28, os fariseus dizem ser discípulos de Moisés, e não de Abraão."},
 {"t":"cv","p":"Depois de ser expulso, o homem ouviu Jesus, disse 'Creio, Senhor' e o adorou.","c":true,"v":38,"e":"No versículo 38, depois que Jesus se revela como o Filho do Homem, o homem diz 'Creio, Senhor' e o adora."}
]}

João 20 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Maria Madalena viu ao chegar ao sepulcro de madrugada?","o":["A pedra revolvida","Guardas na entrada","O sepulcro ainda fechado","Outras mulheres com perfumes"],"c":0,"v":1,"e":"No versículo 1, Maria vai ao sepulcro, ainda escuro, e vê que a pedra estava revolvida."},
 {"t":"multipla","p":"Pedro e o outro discípulo correram ao sepulcro. Quem chegou primeiro?","o":["Simão Pedro","O outro discípulo","Os dois chegaram juntos","Nenhum, pois voltaram no caminho"],"c":1,"v":4,"e":"O versículo 4 diz que o outro discípulo correu mais depressa que Pedro e chegou primeiro."},
 {"t":"multipla","p":"Quem Maria pensou que Jesus era quando o viu junto ao sepulcro?","o":["Um anjo","Um dos discípulos","O jardineiro","Um soldado"],"c":2,"v":15,"e":"No versículo 15, Maria responde a Jesus supondo que ele era o jardineiro."},
 {"t":"multipla","p":"O que Maria Madalena anunciou aos discípulos?","o":["Tiraram o Senhor do sepulcro","Os anjos falaram comigo","O sepulcro está vazio","Vi o Senhor!"],"c":3,"v":18,"e":"No versículo 18, Maria anuncia aos discípulos que viu o Senhor e conta o que ele lhe disse."},
 {"t":"multipla","p":"O que Jesus mostrou aos discípulos depois de dizer \"Paz seja com vocês\"?","o":["O sepulcro vazio","As mãos e o lado","Os lençóis de linho","O pano da cabeça"],"c":1,"v":20,"e":"O versículo 20 diz que Jesus mostrou as mãos e o lado, e os discípulos se alegraram."},
 {"t":"cv","p":"Tomé estava com os discípulos quando Jesus apareceu a eles pela primeira vez.","c":false,"v":24,"e":"O versículo 24 diz que Tomé não estava com eles quando Jesus veio."},
 {"t":"cv","p":"Oito dias depois, Jesus apareceu de novo aos discípulos, e dessa vez Tomé estava com eles.","c":true,"v":26,"e":"O versículo 26 conta que, oito dias depois, Tomé estava presente quando Jesus entrou."},
 {"t":"cv","p":"O capítulo afirma que todos os sinais que Jesus fez estão registrados neste livro.","c":false,"v":30,"e":"O versículo 30 diz que Jesus fez muitos outros sinais que não estão registrados neste livro."}
]}

João 15 Â· exercÃ­cios.texto:
{"perguntas":[
{"t":"multipla","p":"Na comparação da videira, quem é o agricultor?","o":["O Pai","Jesus","Os discípulos","Os profetas"],"c":0,"v":1,"e":"No versículo 1, Jesus diz que ele é a videira verdadeira e que seu Pai é o agricultor."},
{"t":"multipla","p":"O que o Pai faz com o ramo que dá frutos?","o":["Ele o corta","Ele o lança no fogo","Ele o limpa, para que produza mais frutos","Ele o deixa como está"],"c":2,"v":2,"e":"No versículo 2, o ramo que dá frutos é limpo para que produza mais frutos ainda."},
{"t":"multipla","p":"O que acontece com quem não permanece em Jesus?","o":["Recebe outra chance de dar fruto","É lançado fora como o ramo e seca","É enxertado em outra videira","É chamado de servo"],"c":1,"v":6,"e":"No versículo 6, quem não permanece em Jesus é lançado fora como o ramo e seca."},
{"t":"multipla","p":"Segundo Jesus, qual é o maior amor?","o":["Guardar todos os mandamentos","Perdoar os inimigos","Amar o Pai acima de tudo","Dar a própria vida pelos seus amigos"],"c":3,"v":13,"e":"No versículo 13, Jesus diz que ninguém tem maior amor do que dar a própria vida pelos seus amigos."},
{"t":"multipla","p":"Por que Jesus chama os discípulos de amigos, e não de servos?","o":["Porque eles o seguiram desde o começo","Porque eles deram muito fruto","Porque lhes tornou conhecido tudo o que ouviu do Pai","Porque o mundo os odeia"],"c":2,"v":15,"e":"No versículo 15, Jesus os chama de amigos porque lhes tornou conhecido tudo o que ouviu do Pai."},
{"t":"cv","p":"Jesus diz que foram os discípulos que o escolheram.","c":false,"v":16,"e":"No versículo 16, Jesus diz o contrário: não foram eles que o escolheram, foi ele quem os escolheu."},
{"t":"cv","p":"Jesus lembra aos discípulos que o servo não é maior do que o seu senhor e que, se perseguiram Jesus, também os perseguirão.","c":true,"v":20,"e":"No versículo 20, Jesus lembra essa palavra e avisa que eles também serão perseguidos."},
{"t":"cv","p":"Jesus diz que o Consolador, o Espírito da verdade, dará testemunho dele e que os discípulos também darão testemunho.","c":true,"v":27,"e":"Nos versículos 26 e 27, o Consolador dará testemunho de Jesus, e os discípulos também, pois estiveram com ele desde o princípio."}
]}

João 18 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Para onde Jesus foi com os discípulos depois de dizer essas palavras?","o":["Para um jardim do outro lado do ribeiro de Cedrom","Para o pátio do templo","Para uma casa em Betânia","Para a margem do rio Jordão"],"c":0,"v":1,"e":"O versículo 1 diz que Jesus foi para o outro lado do ribeiro de Cedrom, onde havia um jardim."},
 {"t":"multipla","p":"O que aconteceu quando Jesus disse \"Sou eu\" aos que o buscavam?","o":["Prenderam-no na mesma hora","Recuaram e caíram por terra","Ajoelharam-se diante dele","Fugiram correndo"],"c":1,"v":6,"e":"O versículo 6 conta que, quando Jesus disse \"Sou eu\", eles recuaram e caíram por terra."},
 {"t":"multipla","p":"Quem Simão Pedro feriu com a espada?","o":["Um soldado da escolta","Judas, o traidor","Malco, servo do sumo sacerdote","O comandante dos guardas"],"c":2,"v":10,"e":"O versículo 10 diz que Pedro cortou a orelha direita do servo do sumo sacerdote, chamado Malco."},
 {"t":"multipla","p":"A quem Jesus foi levado primeiro depois de preso?","o":["A Caifás","A Pilatos","A Herodes","A Anás"],"c":3,"v":13,"e":"O versículo 13 diz que o levaram primeiramente a Anás, sogro de Caifás."},
 {"t":"multipla","p":"Quem perguntou a Pedro: \"Não te vi eu no jardim com ele?\"","o":["Um parente daquele cuja orelha Pedro cortou","A encarregada da porta","O próprio Malco","O sumo sacerdote Caifás"],"c":0,"v":26,"e":"O versículo 26 diz que a pergunta veio de um servo do sumo sacerdote, parente daquele a quem Pedro tinha cortado a orelha."},
 {"t":"cv","p":"Os que levaram Jesus não entraram no pretório para não se contaminarem e poderem comer a Páscoa.","c":true,"v":28,"e":"O versículo 28 diz que não entraram no pretório para não se contaminarem, para poderem comer a Páscoa."},
 {"t":"cv","p":"Jesus disse a Pilatos que o seu reino é deste mundo.","c":false,"v":36,"e":"No versículo 36, Jesus diz: \"Meu reino não é deste mundo\"."},
 {"t":"cv","p":"Quando Pilatos ofereceu soltar o rei dos judeus, todos gritaram pedindo Barrabás.","c":true,"v":40,"e":"O versículo 40 diz que todos gritaram: \"Este não, mas Barrabás!\"."}
]}

João 19 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que os soldados colocaram sobre a cabeça de Jesus?","o":["Um ramo de oliveira","Uma coroa de espinhos","Uma coroa de ouro","Um capuz de linho"],"c":1,"v":2,"e":"No versículo 2, os soldados tecem uma coroa de espinhos e a colocam sobre a cabeça de Jesus."},
 {"t":"multipla","p":"Segundo os judeus, por que Jesus devia morrer de acordo com a lei deles?","o":["Porque se fez Filho de Deus","Porque não pagava tributo a César","Porque curou no sábado","Porque ameaçou destruir o templo"],"c":0,"v":7,"e":"No versículo 7, os judeus dizem que, pela lei deles, Jesus devia morrer porque se fez Filho de Deus."},
 {"t":"multipla","p":"Quando Pilatos perguntou se devia crucificar o rei deles, o que os principais sacerdotes responderam?","o":["Ele é rei só dos galileus","Então solta-o","Não temos rei, senão César","Nosso rei é Herodes"],"c":2,"v":15,"e":"No versículo 15, os principais sacerdotes respondem: \"Não temos rei, senão César.\""},
 {"t":"multipla","p":"Em que línguas estava escrito o título colocado na cruz?","o":["Só em latim","Em aramaico e grego","Em hebraico e egípcio","Em hebraico, latim e grego"],"c":3,"v":20,"e":"O versículo 20 diz que o título estava escrito em hebraico, latim e grego."},
 {"t":"multipla","p":"O que os soldados fizeram com a túnica sem costura de Jesus?","o":["Rasgaram-na em quatro partes","Lançaram sortes sobre ela","Entregaram-na à mãe de Jesus","Queimaram-na"],"c":1,"v":24,"e":"No versículo 24, os soldados decidem não rasgar a túnica e lançam sortes sobre ela."},
 {"t":"cv","p":"Na cruz, Jesus confiou sua mãe ao discípulo a quem amava, e esse discípulo a recebeu em sua casa.","c":true,"v":27,"e":"No versículo 27, Jesus diz ao discípulo \"Eis aí a tua mãe\", e o discípulo a recebe em sua casa."},
 {"t":"cv","p":"Os soldados quebraram as pernas de Jesus, como fizeram com os outros dois crucificados.","c":false,"v":33,"e":"O versículo 33 diz que os soldados viram que Jesus já estava morto e não lhe quebraram as pernas."},
 {"t":"cv","p":"Jesus foi colocado em um sepulcro antigo, onde outras pessoas já tinham sido sepultadas.","c":false,"v":41,"e":"O versículo 41 diz que o sepulcro era novo e que ninguém ainda tinha sido colocado nele."}
]}

João 11 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"O que Jesus fez ao saber que Lázaro estava doente?","o":["Partiu imediatamente para Betânia","Ficou mais dois dias onde estava","Mandou os discípulos na frente","Pediu que trouxessem Lázaro até ele"],"c":1,"v":6,"e":"O versículo 6 diz que Jesus ainda permaneceu dois dias no lugar onde estava."},
 {"t":"multipla","p":"Qual discípulo disse: \"Vamos também nós para morrermos com ele\"?","o":["Pedro","João","Tomé","André"],"c":2,"v":16,"e":"No versículo 16, foi Tomé, chamado Dídimo, quem disse isso aos condiscípulos."},
 {"t":"multipla","p":"O que Jesus declarou a Marta sobre si mesmo?","o":["Eu sou a ressurreição e a vida","Eu sou o pão da vida","Eu sou a luz do mundo","Eu sou o bom pastor"],"c":0,"v":25,"e":"No versículo 25, Jesus diz a Marta: \"Eu sou a ressurreição e a vida\"."},
 {"t":"multipla","p":"Por que Marta hesitou quando Jesus mandou tirar a pedra?","o":["A pedra era pesada demais","Os judeus não permitiam","Era dia de sábado","Já fazia quatro dias e havia mau odor"],"c":3,"v":39,"e":"No versículo 39, Marta diz que já exalava mau odor, pois já se passaram quatro dias."},
 {"t":"multipla","p":"Quem disse no Sinédrio que convinha que um homem morresse pelo povo?","o":["Anás","Caifás","Nicodemos","Pilatos"],"c":1,"v":50,"e":"Nos versículos 49 e 50, Caifás, sumo sacerdote naquele ano, disse isso."},
 {"t":"cv","p":"Quando soube que Jesus vinha, Maria foi ao encontro dele, e Marta ficou sentada em casa.","c":false,"v":20,"e":"O versículo 20 diz o contrário: Marta foi ao encontro de Jesus, e Maria permaneceu sentada em casa."},
 {"t":"cv","p":"Lázaro saiu do túmulo com as mãos e os pés atados com ataduras e o rosto envolto em um lenço.","c":true,"v":44,"e":"O versículo 44 descreve Lázaro saindo assim, e Jesus manda desatá-lo."},
 {"t":"cv","p":"Depois que passaram a tramar sua morte, Jesus passou a andar abertamente entre os judeus em Jerusalém.","c":false,"v":54,"e":"O versículo 54 diz que Jesus já não andava publicamente e se retirou para a cidade de Efraim com os discípulos."}
]}

João 16 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"De onde Jesus diz que os discípulos serão expulsos?","o":["Do templo","Das sinagogas","Da cidade de Jerusalém","Da casa de seus pais"],"c":1,"v":2,"e":"No versículo 2, Jesus diz: \"Vocês serão expulsos das sinagogas\"."},
 {"t":"multipla","p":"Por que Jesus diz que convém que ele vá?","o":["Para preparar um lugar no céu","Para escapar dos que queriam matá-lo","Porque, se não for, o Consolador não virá","Porque os discípulos já estavam prontos"],"c":2,"v":7,"e":"No versículo 7, Jesus explica que, se ele não for, o Consolador não virá, mas, se for, ele o enviará."},
 {"t":"multipla","p":"A respeito de quê o Consolador convencerá o mundo?","o":["Do pecado, da justiça e do juízo","Da fé, da esperança e do amor","Da lei, dos profetas e da graça","Do arrependimento, do batismo e do perdão"],"c":0,"v":8,"e":"No versículo 8, Jesus diz que o Consolador convencerá o mundo a respeito do pecado, da justiça e do juízo."},
 {"t":"multipla","p":"O que o Espírito da Verdade fará quando vier?","o":["Falará por si mesmo","Guiará os discípulos em toda a verdade","Julgará o príncipe deste mundo","Levará os discípulos para o Pai"],"c":1,"v":13,"e":"No versículo 13, Jesus diz que o Espírito da Verdade os guiará em toda a verdade, sem falar por si mesmo."},
 {"t":"multipla","p":"Que comparação Jesus usa para mostrar que a tristeza vai se converter em alegria?","o":["Um semeador que espera a colheita","Um pai que reencontra o filho","Um pastor que acha a ovelha perdida","Uma mulher que dá à luz"],"c":3,"v":21,"e":"No versículo 21, Jesus fala da mulher que tem tristeza na hora do parto, mas esquece a aflição depois que o menino nasce."},
 {"t":"cv","p":"Os discípulos entenderam logo o que Jesus quis dizer com \"um pouco\".","c":false,"v":18,"e":"No versículo 18, os discípulos dizem entre si: \"Não entendemos o que ele quer dizer\"."},
 {"t":"cv","p":"Jesus diz que, até aquele momento, os discípulos não tinham pedido nada em nome dele.","c":true,"v":24,"e":"No versículo 24, Jesus diz: \"Até agora vocês não pediram nada em meu nome\"."},
 {"t":"cv","p":"Jesus diz aos discípulos que, no mundo, eles não enfrentarão aflições.","c":false,"v":33,"e":"No versículo 33, Jesus diz que no mundo eles enfrentarão aflições, mas que tenham bom ânimo, porque ele venceu o mundo."}
