João 21 Â· exercÃ­cios.texto:
{"perguntas":[
 {"t":"multipla","p":"Quem disse aos outros: \"Vou pescar\"?","o":["Simão Pedro","Tomé","Natanael","Um dos filhos de Zebedeu"],"c":0,"v":3,"e":"No versículo 3, Simão Pedro anuncia que vai pescar e os outros decidem ir com ele."},
 {"t":"multipla","p":"Para que lado do barco Jesus mandou lançar a rede?","o":["Para o lado esquerdo","Para a parte da frente","Para o lado direito","Para a parte de trás"],"c":2,"v":6,"e":"No versículo 6, Jesus manda lançar a rede para o lado direito do barco."},
 {"t":"multipla","p":"O que Pedro fez ao ouvir que era o Senhor?","o":["Ficou no barco puxando a rede","Cingiu-se com a sua veste e lançou-se ao mar","Ajoelhou-se e começou a orar","Correu para avisar os outros discípulos"],"c":1,"v":7,"e":"No versículo 7, Pedro se cinge com a veste e se lança ao mar."},
 {"t":"multipla","p":"O que os discípulos viram ao descerem à terra?","o":["Uma rede nova e um barco","Somente Jesus esperando de pé","Uma mesa com vinho e frutas","Brasas com um peixe em cima e também pão"],"c":3,"v":9,"e":"No versículo 9, eles veem brasas de uma fogueira com um peixe em cima e pão."},
 {"t":"multipla","p":"Por que Pedro se entristeceu durante a conversa com Jesus?","o":["Porque Jesus o chamou de traidor","Porque Jesus mandou que ele voltasse a pescar","Porque Jesus perguntou pela terceira vez se ele o amava","Porque Jesus disse que iria embora"],"c":2,"v":17,"e":"No versículo 17, Pedro se entristece porque Jesus pergunta pela terceira vez: Tu me amas?"},
 {"t":"cv","p":"A rede se rompeu por causa da grande quantidade de peixes.","c":false,"v":11,"e":"O versículo 11 diz que, apesar de serem tantos peixes, a rede não se rompeu."},
 {"t":"cv","p":"Ao falar que outro cingiria Pedro e o levaria para onde ele não desejava, Jesus indicava o tipo de morte com que Pedro glorificaria a Deus.","c":true,"v":19,"e":"O versículo 19 explica que Jesus disse isso indicando o tipo de morte com que Pedro glorificaria a Deus."},
 {"t":"cv","p":"Jesus afirmou que o discípulo a quem amava não morreria.","c":false,"v":23,"e":"O versículo 23 esclarece que Jesus não disse que ele não morreria, mas apenas: Se eu quiser que ele permaneça até que eu venha, que te importa?"}
]}
